INSERT INTO `units` (`id`, `subject_id`, `title`, `description`, `order_index`) VALUES
(1, 1, 'Unidade 1: Matemática Básica & Porcentagem', 'Fundamentos essenciais de cálculos percentuais e proporcionalidade.', 0),
(2, 1, 'Unidade 2: Álgebra & Funções', 'Equações, funções de 1º e 2º grau, logaritmos e progressões.', 0),
(3, 1, 'Unidade 3: Geometria Plana & Espacial', 'Áreas, perímetros, volumes de sólidos, trigonometria e geometria analítica.', 0),
(4, 1, 'Unidade 4: Estatística & Combinatória', 'Análise de dados estatísticos, probabilidades, combinatória e matrizes.', 0),
(5, 2, 'Unidade 1: Mecânica & Cinemática', 'Movimento retilíneo, aceleração, queda livre e leis de Newton.', 0),
(6, 2, 'Unidade 2: Energia & Hidrostática', 'Trabalho mecânico, conservação de energia, impulsos e pressão de fluidos.', 0),
(7, 2, 'Unidade 3: Termologia & Óptica', 'Escalas termométricas, calorimetria, termodinâmica e lentes.', 0),
(8, 2, 'Unidade 4: Eletricidade & Ondulatória', 'Cargas elétricas, circuitos, potência elétrica e ondas.', 0),
(9, 3, 'Unidade 1: Química Geral & Atômica', 'Modelos atômicos, tabela periódica, ligações químicas e radioatividade.', 0),
(10, 3, 'Unidade 2: Soluções & Estequiometria', 'Geometria molecular, soluções aquosas, titulação e gases.', 0),
(11, 3, 'Unidade 3: Físico-Química', 'Termoquímica, cinética, equilíbrio químico, pH e eletroquímica.', 0),
(12, 3, 'Unidade 4: Química Orgânica', 'Cadeias de carbono, funções oxigenadas, nitrogenadas e polímeros.', 0),
(13, 4, 'Unidade 1: Citologia & Metabolismo Celular', 'Organelas, transporte de membrana, respiração, fotossíntese e mitose.', 0),
(14, 4, 'Unidade 2: Ecologia & Meio Ambiente', 'Fluxo de energia, relações ecológicas, ciclos biogeoquímicos e biomas.', 0),
(15, 4, 'Unidade 3: Genética & Evolução', 'Leis de Mendel, sistema ABO, biotecnologia e neodarwinismo.', 0),
(16, 4, 'Unidade 4: Fisiologia & Botânica/Zoologia', 'Sistemas humanos, imunologia, grupos de plantas e reino animal.', 0),
(17, 5, 'Unidade 1: Interpretação & Gêneros Textuais', 'Compreensão textual, coesão, coerência, variação linguística e ambiguidade.', 0),
(18, 5, 'Unidade 2: Gramática & Sintaxe', 'Morfologia, estrutura sintática, regência, concordância e pontuação.', 0),
(19, 5, 'Unidade 3: Semântica & Estilo', 'Figuras de linguagem, funções da linguagem, conotação e redação.', 0),
(20, 5, 'Unidade 4: Literatura Brasileira', 'Escolas literárias do Barroco, Romantismo, Realismo ao Modernismo.', 0),
(21, 6, 'Unidade 1: História do Brasil', 'Período colonial, império, Vargas, ditadura militar e redemocratização.', 0),
(22, 6, 'Unidade 2: História Geral', 'Antiguidade clássica, idade média, revoluções e guerras mundiais.', 0),
(23, 6, 'Unidade 3: Geografia Física & Humana', 'Relevo, climas, hidrografia, urbanização e demografia brasileira.', 0),
(24, 6, 'Unidade 4: Geopolítica & Meio Ambiente', 'Globalização, blocos econômicos, matriz energética e cartografia.', 0);
